/** Regulatory class in NEXVO ↔ class letter in the decree (art. 2-B). */
export const CLASS_LETTER = { HOUSEHOLD_SIMILAR: "MA", INERT: "I", SPECIAL: "S", SPECIAL_HAZARDOUS: "SD" } as const satisfies Record<string, NomenclatureClass>;

export function findNomenclature(code: string, cls: NomenclatureClass): NomenclatureEntry | undefined {
  return NOMENCLATURE_06_104.find((e) => e[0] === code && e[1] === cls);
}
